function f0(x, sr){ // autocorrelation pitch over voiced frames, median
  const win=Math.round(sr*0.04), hop=Math.round(sr*0.02), lo=Math.round(sr/400), hi=Math.round(sr/70); const v=[];
  for(let s=0;s+win+hi<x.length;s+=hop){ let e=0; for(let i=0;i<win;i++)e+=x[s+i]**2; if(e/win<1e-4)continue;
    let best=0,bl=0; for(let l=lo;l<=hi;l++){let c=0;for(let i=0;i<win;i++)c+=x[s+i]*x[s+i+l]; if(c>best){best=c;bl=l;}}
    if(best/e>0.5)v.push(sr/bl);} v.sort((a,b)=>a-b); return v.length?Math.round(v[v.length>>1]):0; }
async function get(name){ return new Promise(res=>{const ws=new WebSocket("ws://127.0.0.1:3001/voice"); const chunks=[]; let sr=24000, greeted=false;
 ws.onopen=()=>ws.send(JSON.stringify({type:"start",name,sex:"male",apparent_age:70}));
 ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.type==="reply"&&m.audio){chunks.push(Buffer.from(m.audio,"base64"));sr=m.sampleRate;} if(m.type==="reply"&&m.done){ws.close();const b=Buffer.concat(chunks);const x=new Float32Array(b.length>>1);for(let i=0;i<x.length;i++)x[i]=b.readInt16LE(i*2)/32768;res(f0(x,sr));}};});}
console.log("median pitch, your clone (Jeffrey):", await get("Jeffrey"), "Hz");
console.log("median pitch, stock voice (no clone):", await get("Nobody"), "Hz");
process.exit();
EOF
